    /**
 * 触发指定事件
 * @param {any} id
 * @param {any} eventName
 * @param {any} param
 */
    owner.trigger = function (id, eventName) {
     
        eventName = eventName || "click";
        var e = null;
        if (id instanceof HTMLElement) {
            e = id;
        }else {
            var p = new RegExp("[\\.\\# ]");
            if (p.test(id)) {
                e = document.querySelector(id);
            } else {
                e = document.getElementById(id);
            }
        }
        if (e) {
            switch (eventName) {
                case "click":
                    if (/msie/i.test(navigator.userAgent)) //IE
                    {
                        e.fireEvent("onclick");
                    } else {
                        var e1 = document.createEvent('MouseEvent');
                        e1.initEvent('click', false, false);
                        e.dispatchEvent(e1);
                    }
                    break;
            }
        }
        return false;
    };

