    owner.getValue = function (id) {
        if (owner.base.IsString(id)) {
            var e1 = document.getElementById(id);
        } else {
            e1 = id;
        }
        if (e1) {
            switch (e1.nodeName) {
                case "INPUT":
                    var type = e1.getAttribute("type");
                    switch (type) {
                        case "checkbox":
                            if (e1.checked) return e1.value;
                            else return null;
                        case "file":
                            return e1.files[0];
                        case "password":
                        case "text":
                        default:
                            return e1.value;
                    }
                case "SELECT":
                    var index = e1.selectedIndex;
                    if (index === -1) return "";
                    else {
                        return e1.options[index].value;
                    }
                case "TEXTAREA":
                    return e1.value;
                default:
                    return "";
            }
        } else return "";
    };
    owner.setValue = function (id, val) {
        if (owner.base.IsString(id)) {
            document.getElementById(id).value = val;
            return;
        } else {
            e1 = id;
        }
        if (e1) {
            switch (e1.nodeName) {
                case "SPAN":
                    e1.innerHTML = val;
                    return;
                case "INPUT":
                    var type = e1.getAttribute("type");
                    switch (type) {
                        case "checkbox":
                            if (val === "true" || val === true) {
                                e1.checked = true;
                            } else {
                                e1.checked = false;
                            }
                            return;
                        case "password":
                        case "text":
                        default:
                            e1.value = val;
                            return;
                    }
                case "SELECT":
                    for (var option in e1.options) {
                        if (e1.options[option].value === val) {
                            e1.options[option].setAttribute("selected", "selected");
                            break;
                        }
                    }
                    return;
                case "TEXTAREA":
                case "SPAN":
                default:
                    e1.innerHTML = val;
                    return;
            }
        } else return;

    };
