    owner.toast = function (msg, level) {
        level = level || "info";
        if (typeof mui !== "undefined") {
            mui.toast(msg);
        } else {
            var bb = document.createElement("div");
       
            bb.innerHTML = '<span class=\"'+level+'\">'+ msg+'</span>';
            bb.setAttribute("class", "com-toast");

            var len = msg.length;
            len = len / 6;
            if (len < 4) len = 4;
            else if (len > 20) len = 20;

            switch (level) {
                case "err":
                    len = parseInt( len * 1.5);
                    break;
                case "warn":
                    len = parseInt(len * 1.1);
                    break;
            }
       
            document.body.appendChild(bb);
            var hide = function () {
                try {
                    document.body.removeChild(bb);
                } catch (e) { }
            };
           /*自动隐藏信息层*/
            setTimeout(hide, len * 500);

            bb.addEventListener("click", function () {
                try {
                    clearTimeout(hide);
                } catch (e) {}
                this.parentNode.removeChild(this);

            });
         
          

        }
    };
