    /**
     * 提示框
     * @param {any} title 标题
     * @param {any} msg 提示文本
     * @param {any} def 默认值 
     * @param {any} okcallBack 确定回调
     * @param {any} cancelCallBack  取消回调
     * @param {any} inputType  输入框类型（password or text)
     */
    owner.prompt = function (title, msg, def, okcallBack, cancelCallBack, inputType) {
        var btns = ['确认', '取消'];
        if (def === "#confirm#") {
            mui.confirm(msg, title, btns, function (e) {
                if (e.index === 0 && okcallBack) okcallBack();
                else if (cancelCallBack) cancelCallBack();
            });
        } else {
            inputType = inputType || "text";
            mui.prompt(msg, def, title, btns, function (e) {
                if (e.index === 0 && okcallBack) okcallBack(e.value);
                else if (cancelCallBack) cancelCallBack();
            }, inputType);
        }

    };

    owner.base = {
        IsJsonString: function (o) {
            if (this.IsString(o)) {
                return /^\s*?\{[\s\S]*?\}\s*?$/.test(o);
            }
            return false;
        },
        IsString: function (o) {
            return typeof (o) === "string";
        },
        isObj: function (o) {
            return typeof (o) === "object";
        },
        isNull: function (o) {
            return gettype.call(o) === "[object Null]";
        },
        isArray: function (o) {
            return gettype.call(o) === "[object Array]";
        },
        isDocument: function () {
            return gettype.call(o) === "[object Document]" || "[object HTMLDocument]";
        },
        buildForm: function (e) {
            var form = {};
            var es = e.querySelectorAll("[name]");
            for (var i = 0; i < es.length; i++) {

                var el = es[i];
                if (el.name) {
                    var val = owner.getValue(el);
                    if (form[el.name]) {
                        form[el.name] = form[el.name] + ',' + val;
                    } else {
                        form[el.name] = val;
                    }
                }
            }
            return form;

        },
        //把表单对象转化为json字符串
        FormDataToJson: function (formData) {
            return JSON.stringify(formData);
        },
        GetQuery: function (url, param) { //获取地址中的参数
            var p = "?" + param + "=";
            var index = url.indexOf(p);
            if (index < 0) index = url.indexOf("&" + param + "=");
            if (index >= 0) {
                var u = url.substr(index + p.length);
                index = u.indexOf("&");
                if (index === 0) return "";
                if (index > 0) {
                    return u.substr(0, index);
                } else return u;
            } else {
                return null;
            }

        },
        GetFullUrl: function (url) {
            if (url.indexOf("://") > 0) {
                return url;
            }
            var u = location.protocol + "//" + location.host;

            if (url[0] != "/") u = u + "/" + url;
            else u = u + url;
            return u;
        },
        //从父级元素中找含指定的类名的元素
        findParentByClass: function (e, className) {
            var postE = e.parentNode;
            while (postE && postE.tagName != "body") {
                try {
                    if (postE.classList && postE.classList.contains(className)) {
                        return postE;
                    }
                    else {
                        postE = postE.parentNode;
                    }
                } catch (e) {
                    return null;
                } 

            }
            return null;
        },
        //从父级元素中找含有指定属性的元素,floor,多少个上级中找
        findParentByAttr: function (e, attrName, stopE) {
            var postE = e.parentNode;
            stopE = stopE || document.body;
            while (postE && postE.tagName !== "body") {
                try {
                    if (postE.hasAttribute(attrName)) {
                        return postE;
                    }
                    else {
                        postE = postE.parentNode;
                        if (postE === stopE) return null;
                    }
                } catch (e) {
                    return null;
                }

            }
            return null;
        }
    };



    //ajax
    owner.ajax = function (options) {
        options = options || {};
        options.type = (options.type || "GET").toUpperCase();
        options.async = options.async || true;
        options.dataType = (options.dataType || "json").toLowerCase();
        var xhr;
        //创建ajax请求对象
        xhr = new XMLHttpRequest();
        //连接和发送数据

        if (options.type === "GET") {
            var params = formatParams(options.data);
            xhr.open(options.type, options.url + (params ? params : ""), options.async);
            xhr.send(null);
        } else {
            xhr.open(options.type, options.url, options.async);
            //设置表单提交时的内容类型

            switch (options.dataType) {
                case "bin": //上传二进制流
                    xhr.overrideMimeType("application/octet-stream");
                    xhr.setRequestHeader("Content-Type", "application/octet-stream");
                    break;
                case "json":
                    xhr.setRequestHeader("Content-Type", "application/json");
                    if (owner.base.isObj(options.data)) {
                        options.data = JSON.stringify(options.data);
                    }
                    break;
                case "put":
                case "text":
                    xhr.setRequestHeader("Content-Type", "text/plain");
                    break;
                case "form":
                    xhr.setRequestHeader("Content-Type", "application/x-www-form-urlencoded");
                    if (owner.base.isObj(options.data)) {
                        options.data = formatParams(options.data);
                    }
                    break;
                case "file":
                    //转换data为formdata;
                    if (options.data) {
                        var formdata = new FormData();
                        for (var name in options.data) {
                            formdata.append(name, options.data[name]);
                        }
                        options.data = formdata;
                    }
                    break;
                default:
                    xhr.setRequestHeader("Content-Type", "application/x-www-form-urlencoded");
                    break;
            }
            //带上jwtToken
            if (owner.Bearer) {
                xhr.setRequestHeader("Authorization", "Bearer " + owner.Bearer);
            }
            if (options.dataType == "bin" && xhr.sendAsBinary) {
                xhr.sendAsBinary(options.data);
            }
            xhr.send(options.data);
        }

        //接收处理
        xhr.onreadystatechange = function () {
            if (xhr.readyState === 4) {
                var status = xhr.status;
                if (window.plus && plus.nativeUI) {
                    try {//关闭mui等待框
                        plus.nativeUI.closeWaiting();
                    } catch (ex) { console.log(ex); }
                }

                if (status >= 200 && status < 300 || status === 304) {
                    var obj = xhr.responseText;
                    if (options.dataType !== "json") {
                        if (owner.base.IsJsonString(obj)) { //json格式
                            obj = JSON.parse(obj);
                        } else {
                            obj = { state: "ok", data: obj };
                        }

                    } else {
                        if (owner.base.IsJsonString(obj)) {
                            obj = JSON.parse(obj);
                        } else {
                            obj = { state: "err", msg: obj.toString() };
                        }

                    }
                    try {
                        options.success && options.success(obj);
                        options.any && options.any(obj);
                    } catch (ex) {
                        console.log(ex);
                    }


                } else {
                    console.log(status + ":请求失败" + options.url);
                }


            }
        };
    };

    owner.link = function (a) {
        var dataType = a.getAttribute("data-type") || "";
        if (dataType === "build") {
            owner.showBuilding();
            return false;
        }
        var href = a.getAttribute(attrLink) || a.getAttribute("href") || "";
        if (href === "#" || href === "") return false;
        var screenType = a.getAttribute("data-screen") || "";

        if (screenType !== "") {
            if (screenType === "heng") {
                if (window.plus) {
                    plus.screen.lockOrientation("landscape-primary");
                }
            }
        }

        owner.playAudio();
        if (window.plus) {
            switch (dataType) {
                case "rand":
                case "vip-rand":
                    var now = new Date();
                    var t = now.getYear() + ((now.getMonth() + 1) < 10 ? "0" : "") + (now.getMonth() + 1) +
                        (now.getDate() < 10 ? "0" : "") + Math.random();
                    href = href + "?_=" + t;
                    break;
                case "vip-day":
                    now = new Date();
                    t = now.getYear() + ((now.getMonth() + 1) < 10 ? "0" : "") + (now.getMonth() + 1) +
                        (now.getDate() < 10 ? "0" : "");
                    href = href + "?_=" + t;

                    break;

            }
            href = owner.GetFullUrl(href);


            setTimeout(function () { openPage(href); }, 10);
            return false;
        } else {
            //方式一:在新窗口中打开,点击返回直接关闭窗口
            //if (a.getAttribute("href") != href) {
            //    a.setAttribute("href", href);
            //}
            //return true;
            //结束

            //方式二，在当前窗口打开，点击返回直接回退1步
            location.href = href;
            return false;
        }


    };

    //格式化参数
    function formatParams(data) {
        var arr = [];
        for (var name in data) {
            arr.push(encodeURIComponent(name) + "=" + encodeURIComponent(data[name]));
        }
        return arr.join("&");
    }
    owner.log = function (msg) {
        console.log(msg);
    };
    owner.err = function (e) {
        console.error(e);
    };

    //遍历元素，调用方法owner.foreach(array,function(e,index){});
    owner.each = owner.foreach = function (array, fn) {
        for (var i = 0; i < array.length; i++) {
            if (fn(array[i]) === true) break;
        }
    };

    //添加事件
    owner.addEvent = function (element, type, fn) {
        if (element.addEventListenner) {
            element.addEventListenner(type, fn, true);
        } else if (element.attachEvent) {
            element.attachEvent('on' + type, fn);
        } else {
            element['on' + type] = fn;
        }
    };

    //删除事件,IE10以下移除的事件只能运行(定义）一次，多次无效果
    owner.removeEvent = function (element, type, fn) {
        if (element.removeEventListenner) {
            element.removeEventListenner(type, fn, true);
        } else if (element.detachEvent) {
            element.detachEvent('on' + type, fn);
        } else {
            element['on' + type] = null;
        }
    };

    /**
     * 动态加载js文件
     * @param {element} 脚本插入位置,插入到指定元素内
     * @param {string} name 脚本名称
     * @param {string} url 脚本地址
     * @param {function} callback  脚本加载后执行的函数
     */
    owner.loadJs = function (element, name, url, callback) {
        element = element || document.body;
        var head = document.getElementsByTagName('head')[0];
        var script = document.createElement('script');
        script.type = 'text/javascript';
        script.setAttribute("name", name);
        script.src = url;
        if (typeof (callback) === 'function') {
            script.onload = script.onreadystatechange = function () {
                if (!this.readyState || this.readyState === "loaded" || this.readyState === "complete") {
                    callback();
                    script.onload = script.onreadystatechange = null;
                }
            };
        }
        element.appendChild(script);
    }


    /**
     * 移除js
     * @param {any} names
     */
    owner.unloadJs = function (names) {

        for (var i = 0; i < names.length; i++) {
            var ems = document.getElementsByName(names[i]);
            for (var j = 0; j < ems.len; j++) {
                if (ems[j].tagName === "SCRIPT") {
                    ems[j].parentNode.removeChild(ems[j]);
                }
            }
        }
    }


    /**
     * 动态加载js代码
     * @param {element} 脚本插入位置,插入到指定元素内
     * @param {string} code 脚本代码
     * @param {string} name 脚本名称
     */
    owner.loadJsCode = function (element, name, code) {
        element = element || document.body;
        var script = document.createElement("script");
        script.type = "text/javascript";
        if (name) {
            script.setAttribute("name", name);
        }
        try {
            // firefox、safari、chrome和Opera
            script.appendChild(document.createTextNode(code));
        } catch (ex) {
            // IE早期的浏览器 ,需要使用script的text属性来指定javascript代码。
            script.text = code;
        }
        element.appendChild(script);
    };
